<script setup lang="ts">
import { computed, ref } from "vue";
import { onLoad } from "@dcloudio/uni-app";
import MNavBar from "../../../components/MNavBar.vue";
import { learnApi } from "../../../services/learnApi";
import { obj, str } from "../../../features/attempt/attemptModel";
type Fav={refType:string;refId:string;title:string};type Note={id:string;refType:string;refId:string;content:string;title:string};
const tab=ref<"favorites"|"notes">("favorites");const filter=ref("all");const favs=ref<Fav[]>([]);const notes=ref<Note[]>([]);const loading=ref(true);const busy=ref(false);const error=ref("");const note=ref("");const editor=ref(false);const editId=ref("");const editType=ref("");const editRef=ref("");const editContent=ref("");
const filtered=computed(()=>favs.value.filter(x=>filter.value==="all"||x.refType===filter.value));
function list(raw:unknown):unknown[]|null{const x=obj(raw);return Array.isArray(raw)?raw:Array.isArray(x.items)?x.items:Array.isArray(x.records)?x.records:null;}
function parseFav(raw:unknown):Fav[]|null{const x=obj(raw);let rows=list(raw);if(!rows){rows=Object.entries(x).flatMap(([key,value])=>Array.isArray(value)?value.map(v=>({...obj(v),refType:key})):[]);}const mapped=rows.map(v=>{const x=obj(v),refType=str(x.refType??x.type),refId=str(x.refId??x.id);return ["question","lesson","formula","node"].includes(refType)&&/^[1-9]\d*$/.test(refId)?{refType,refId,title:str(x.title??x.name??x.stem)||`${refType} #${refId}`}:null;});return mapped.some(x=>x===null)?null:mapped as Fav[];}
function parseNotes(raw:unknown):Note[]|null{const rows=list(raw);if(!rows)return null;const mapped=rows.map(v=>{const x=obj(v),id=str(x.id),content=str(x.content);return /^[1-9]\d*$/.test(id)?{id,content,refType:str(x.refType),refId:str(x.refId),title:str(x.title)}:null;});return mapped.some(x=>x===null)?null:mapped as Note[];}
async function load(){loading.value=true;error.value="";try{const [a,b]=await Promise.allSettled([learnApi.favorites(),learnApi.notes()]);if(a.status==="fulfilled"){const mapped=parseFav(a.value);if(mapped)favs.value=mapped;else throw new Error("收藏列表字段尚未对齐");}else throw a.reason;if(b.status==="fulfilled"){const mapped=parseNotes(b.value);if(mapped)notes.value=mapped;else throw new Error("笔记列表字段尚未对齐");}else throw b.reason;}catch(e){error.value=e instanceof Error?e.message:"学习资料暂不可用";}finally{loading.value=false;}}
function openEdit(n?:Note){editId.value=n?.id||"";editType.value=n?.refType||"";editRef.value=n?.refId||"";editContent.value=n?.content||"";editor.value=true;note.value="";}
async function save(){if(busy.value||!editContent.value.trim()||!["question","lesson","formula","node"].includes(editType.value)||!/^[1-9]\d*$/.test(editRef.value))return;busy.value=true;error.value="";try{await learnApi.saveNote({content:editContent.value.trim(),refType:editType.value,refId:editRef.value},editId.value||undefined);const raw=await learnApi.notes(),mapped=parseNotes(raw);if(!mapped||!mapped.some(x=>x.content===editContent.value.trim()&&x.refType===editType.value&&x.refId===editRef.value))throw new Error("保存请求已返回，但回读未确认笔记内容");notes.value=mapped;editor.value=false;note.value="笔记已由服务端确认。";}catch(e){error.value=e instanceof Error?e.message:"笔记尚未保存";}finally{busy.value=false;}}
async function removeNote(n:Note){if(busy.value)return;uni.showModal({title:"删除笔记",content:"删除后无法在本机撤销，确认删除？",success:r=>{if(r.confirm)void doRemoveNote(n);}});}
async function doRemoveNote(n:Note){busy.value=true;error.value="";try{await learnApi.deleteNote(n.id);await load();}catch(e){error.value=e instanceof Error?e.message:"删除未确认";}finally{busy.value=false;}}
async function removeFav(f:Fav){if(busy.value)return;busy.value=true;error.value="";try{await learnApi.removeFavorite(f.refType,f.refId);await load();}catch(e){error.value=e instanceof Error?e.message:"移除收藏失败";}finally{busy.value=false;}}
function inputValue(event:unknown):string{const e=event as {detail?:{value?:unknown}};return typeof e?.detail?.value==="string"?e.detail.value:"";}
onLoad(q=>{if(q?.tab==="notes")tab.value="notes";if(q?.refType&&q?.refId){editType.value=String(q.refType);editRef.value=String(q.refId);}void load();});
</script>
<template><view class="mobile-page"><MNavBar :title="editor?'编辑笔记':'收藏与笔记'" back/><scroll-view scroll-y class="screen"><view class="page-scroll"><template v-if="editor"><view class="editor-head"><text class="eyebrow">PERSONAL NOTES</text><text class="page-title">写下你自己的理解</text></view><text class="m-field-label">关联资源类型</text><picker :range="['question','lesson','formula','node']" @change="editType=['question','lesson','formula','node'][Number($event.detail.value)]"><view class="m-input picker">{{editType||'请选择关联类型'}}</view></picker><text class="m-field-label">关联资源编号</text><input class="m-input" type="number" :value="editRef" placeholder="输入服务端资源编号" @input="editRef=inputValue($event)"/><text class="m-field-label">笔记正文</text><textarea class="note-input" :value="editContent" maxlength="10000" placeholder="记录思路、疑问与下一步…" @input="editContent=inputValue($event)"/><view v-if="error" class="m-state error">{{error}}</view><view class="editor-actions"><button class="m-button secondary" @click="editor=false">返回列表</button><button class="m-button" :disabled="busy||!editContent.trim()||!editType||!editRef" @click="save">{{busy?'保存中…':'保存并核对'}}</button></view></template>
  <template v-else><view class="head"><text class="eyebrow">YOUR LEARNING LIBRARY</text><text class="page-title">把重要的线索留在手边</text></view><view class="tabs"><button :class="{active:tab==='favorites'}" @click="tab='favorites'">我的收藏</button><button :class="{active:tab==='notes'}" @click="tab='notes'">学习笔记</button></view><view v-if="loading" class="m-state">正在读取个人资料…</view><view v-else-if="error" class="m-state error">{{error}}<button class="retry" @click="load">重试</button></view><template v-else-if="tab==='favorites'"><scroll-view scroll-x class="filters"><view><button v-for="f in [{k:'all',t:'全部'},{k:'question',t:'题目'},{k:'lesson',t:'课时'},{k:'formula',t:'公式'},{k:'node',t:'知识点'}]" :key="f.k" :class="{active:filter===f.k}" @click="filter=f.k">{{f.t}}</button></view></scroll-view><view v-if="!filtered.length" class="m-state">这个分组暂无收藏。</view><view v-for="f in filtered" :key="f.refType+f.refId" class="m-list-row"><view class="body"><text class="title">{{f.title}}</text><text class="meta">{{f.refType}} #{{f.refId}}</text></view><button class="small" :disabled="busy" @click="removeFav(f)">移除</button></view></template>
    <template v-else><button class="m-button add" @click="openEdit()">新建笔记</button><view v-if="!notes.length" class="m-state">还没有学习笔记。</view><view v-for="n in notes" :key="n.id" class="m-card"><text class="m-card-title">{{n.title||n.refType+' #'+n.refId}}</text><text class="excerpt">{{n.content}}</text><view class="note-actions"><button @click="openEdit(n)">编辑</button><button :disabled="busy" @click="removeNote(n)">删除</button></view></view></template><view v-if="note" class="m-state success">{{note}}</view></template></view></scroll-view></view></template>
<style scoped>.screen{height:calc(100vh - 92rpx)}.head,.editor-head{display:flex;flex-direction:column;gap:12rpx;margin:8rpx 0 27rpx}.tabs{display:flex;padding:7rpx;background:#eaf0f8;border-radius:20rpx;margin-bottom:21rpx}.tabs button{flex:1;min-height:73rpx;background:transparent;color:#697b94;font-size:25rpx}.tabs button.active{border-radius:15rpx;background:white;color:#2559cd;font-weight:800}.filters{white-space:nowrap;margin-bottom:21rpx}.filters view{display:flex;gap:8rpx}.filters button{flex:none;padding:10rpx 20rpx;border-radius:99rpx;background:#eaf0f8;color:#60728d;font-size:21rpx}.filters button.active{background:#2c5ed4;color:white}.small,.note-actions button{padding:11rpx 17rpx;border-radius:13rpx;background:#eef3ff;color:#2859ca;font-size:22rpx}.add{margin:17rpx 0 22rpx}.excerpt{display:block;white-space:pre-wrap;max-height:155rpx;overflow:hidden;color:#455a76;font-size:25rpx;line-height:1.65;margin:17rpx 0}.note-actions{display:flex;gap:13rpx}.picker{display:flex;align-items:center}.note-input{width:100%;min-height:420rpx;padding:21rpx;border:1rpx solid #d9e3f2;border-radius:20rpx;background:white;color:#263a55;font-size:26rpx;line-height:1.6}.editor-actions{display:flex;gap:12rpx;margin-top:25rpx}.editor-actions button{flex:1;font-size:23rpx}.retry{margin-top:15rpx;color:#2556ca;background:#edf3ff}</style>
